select energy_manager.load_cards($cards$[
{"id":"p3-b09-022","paper":3,"topic":"DG Set Systems","kind":"fact","front":"How long can a diesel engine run at 10% overload, and how long can an alternator take 50% overload?","back":"Diesel engine: 10% overload for 1 hour in every 12 hours of operation. Alternator: 50% overload for 15 seconds.","explain":"Overloads that look harmless on utility supply can damage a DG set, so the set should be selected so that overloads stay within these limits. Steady loads give the best performance.","flash":false,"source":"BEE Book 3 Ch 09 p293","order":3449},
{"id":"p3-b09-023","paper":3,"topic":"DG Set Systems","kind":"fact","front":"What engine loading should be maintained for a DG set, and at what alternator loading is efficiency highest?","back":"Engine loading should be kept above 50% (in kW or BHP). Alternators reach their highest efficiency at around 70% loading and above.","explain":"Engine manufacturers publish fuel consumption curves against engine loading. The best operating point for both engine and alternator should be used to reach high efficiency.","flash":false,"source":"BEE Book 3 Ch 09 p293","order":3450},
{"id":"p3-b09-024","paper":3,"topic":"DG Set Systems","kind":"fact","front":"In what order should loads be started on a DG set?","back":"Start the load with the highest transient kVA first, then the others in descending order of starting kVA.","explain":"The base load already running reduces the transient handling capacity. On AC generators it also increases the transient voltage dip, so careful sequencing gives better use of the set.","flash":false,"source":"BEE Book 3 Ch 09 p293","order":3451},
{"id":"p3-b09-025","paper":3,"topic":"DG Set Systems","kind":"fact","front":"What power factor is an AC generator designed for, and what is the economical fix for a low load power factor?","back":"0.8 lagging. The economical option is to add power factor improvement capacitors rather than oversize the generator.","explain":"A low power factor needs higher excitation current, which increases losses. Oversizing the alternator for a low PF lowers its operating efficiency and raises cost.","flash":false,"source":"BEE Book 3 Ch 09 p294","order":3452},
{"id":"p3-b09-026","paper":3,"topic":"DG Set Systems","kind":"fact","front":"Which exhaust source is hotter, and what are the approximate exhaust and cooling water temperatures in a reciprocating engine?","back":"Exhaust gas is at about 450°C, against about 100°C for the cooling water. Each provides about half of the useful thermal energy, but exhaust is more versatile.","explain":"Exhaust is much hotter, so it can drive higher temperature uses. Heat can also be recovered from the lubricating oil, jacket water and charge air coolers.","flash":false,"source":"BEE Book 3 Ch 09 p295","order":3453},
{"id":"p3-b09-027","paper":3,"topic":"DG Set Systems","kind":"fact","front":"What is the formula for the potential waste heat recovery (WHR) from a reciprocating engine?","back":"Potential WHR (kcal/h) = kWh output per hour × 8 kg gas per kWh × 0.25 kcal/kg°C × (t − 180)°C, where t is the gas temperature after the turbocharger.","explain":"The 8 kg/kWh gas flow and 0.25 kcal/kg°C specific heat are the chapter's standard values. The 180°C floor is the lowest allowed exit temperature, set to avoid acid dew point corrosion.","flash":false,"source":"BEE Book 3 Ch 09 p295","order":3454},
{"id":"p3-b09-028","paper":3,"topic":"DG Set Systems","kind":"problem","front":"A 1100 kVA DG set runs at 800 kW with 480°C exhaust gas temperature. What is the potential waste heat recovery?","back":"About 4,80,000 kcal/h (4.8 lakh kcal/h).","explain":"The chapter uses 8 kg of gas per kWh, 0.25 kcal/kg°C, and a 180°C exit floor. The result is the potential only; the realisable recovery depends on the site.","flash":false,"source":"BEE Book 3 Ch 09 p295","steps":[{"prompt":"Find the average kWh generated per hour.","answer":"800 kWh/h (800 kW loading).","explain":"The kWh output per hour equals the load in kW for steady operation."},{"prompt":"Find the exhaust gas flow.","answer":"800 × 8 = 6,400 kg/h.","explain":"The chapter takes 8 kg of exhaust gas per kWh generated."},{"prompt":"Find the usable temperature drop down to the 180°C floor.","answer":"480 − 180 = 300°C.","explain":"180°C is the lowest exit temperature allowed to avoid acid dew point corrosion."},{"prompt":"Compute the heat potential.","answer":"6,400 × 0.25 × 300 = 4,80,000 kcal/h (4.8 lakh kcal/h).","explain":"Heat = flow × specific heat × temperature drop."}],"order":3455},
{"id":"p3-b09-029","paper":3,"topic":"DG Set Systems","kind":"fact","front":"What three factors affect waste heat recovery from DG set flue gases?","back":"DG set loading and exhaust gas temperature; hours of operation; and back pressure on the DG set.","explain":"Continuous operation makes waste heat recovery more cost-effective. The back pressure added by the heat recovery unit must also stay within limits.","flash":false,"source":"BEE Book 3 Ch 09 p296","order":3456},
{"id":"p3-b09-030","paper":3,"topic":"DG Set Systems","kind":"fact","front":"What minimum sustained DG set loading gives a reasonable flue gas flow and temperature for heat recovery?","back":"Over 60% of rating.","explain":"Fluctuating or gross under-loading gives erratic flue gas flow and temperature at the heat recovery unit, which can cause cold end corrosion. At 60% load in the chapter's 5 MW example, the unit gets 325°C inlet and 180°C outlet.","flash":true,"source":"BEE Book 3 Ch 09 p296","order":3457},
{"id":"p3-b09-031","paper":3,"topic":"DG Set Systems","kind":"fact","front":"What is trigeneration?","back":"The simultaneous production of electricity, heat and cooling from one fuel input. In a DG set, waste heat boilers make steam and jacket cooling water runs vapour absorption machines (VAM) for air conditioning.","explain":"Trigeneration optimises fuel utilisation from a diesel or gas engine. The economics depend on the waste heat boiler and VAM capacity matched to the cooling need.","flash":false,"source":"BEE Book 3 Ch 09 p296","order":3458},
{"id":"p3-b09-032","paper":3,"topic":"DG Set Systems","kind":"fact","front":"How long is the standard shop-floor energy performance trial on a DG set, and how often are readings logged?","back":"A 2 hour trial at a steady load, with readings logged every 15 minutes.","explain":"Logged quantities include fuel consumption, amps, volts, PF, kW and kWh, intake air and cooling water temperatures, cylinder exhaust temperatures, turbocharger RPM, charge air pressure, and cooler and stack gas temperatures.","flash":false,"source":"BEE Book 3 Ch 09 p297","order":3459},
{"id":"p3-b09-033","paper":3,"topic":"DG Set Systems","kind":"fact","front":"List five energy saving measures for DG sets.","back":"Any five of: steady load with cold, dust free intake air; better air filtration; fuel storage and handling per manufacturer and oil company guidelines; frequent calibration of fuel injection pumps; following the maintenance checklist; avoiding load fluctuations, phase imbalance and harmonic loads; regular field trials.","explain":"Steady loading and clean intake air protect efficiency. Frequent fuel injection pump calibration and regular trials help keep the set at its best operating point.","flash":false,"source":"BEE Book 3 Ch 09 p298","order":3460},
{"id":"p3-b09-034","paper":3,"topic":"DG Set Systems","kind":"problem","front":"A 180 kVA, 0.8 PF DG set has a 210 BHP engine. With no derating, and with 5.66 kW of alternator losses and exciter power, what is the maximum PF at full load?","back":"About 0.84 (151 kW available ÷ 180 kVA).","explain":"Engine power must be converted to kW, and losses subtracted, before dividing by the kVA rating. Running at this PF avoids overloading the set.","flash":false,"source":"BEE Book 3 Ch 09 p299","steps":[{"prompt":"Convert the engine rating from BHP to kW.","answer":"210 × 0.746 = 156.66 kW.","explain":"1 BHP = 0.746 kW."},{"prompt":"Subtract the alternator losses and exciter power.","answer":"156.66 − 5.66 = 151 kW available to the alternator.","explain":"Only the power left after losses is available as load at the alternator output."},{"prompt":"Divide by the kVA rating to get the maximum PF.","answer":"151 / 180 = 0.84.","explain":"PF = kW / kVA, so this is the highest PF at which full kVA can be delivered without overloading the engine."}],"order":3461},
{"id":"p3-b09-035","paper":3,"topic":"DG Set Systems","kind":"problem","front":"A DG set at 600 kW with 450°C exhaust gas (8 kg gas/kWh, 0.25 kcal/kg°C) drops to 230°C after a heat recovery boiler. How much steam is raised at 3 kg/cm² (enthalpy 650.57 kcal/kg) from 80°C feedwater?","back":"About 462.7 kg/h of steam (heat recovered 2,64,000 kcal/h).","explain":"Steam output is the recovered heat divided by the heat added per kg of steam, which is the steam enthalpy minus the feedwater enthalpy. The chapter's method is used here.","flash":false,"source":"BEE Book 3 Ch 09 p299","steps":[{"prompt":"Find the waste heat recovered.","answer":"600 × 8 × 0.25 × (450 − 230) = 2,64,000 kcal/h.","explain":"The heat recovered is kWh per hour × gas per kWh × specific heat × temperature drop."},{"prompt":"Find the heat added per kg of steam.","answer":"650.57 − 80 = 570.57 kcal/kg.","explain":"The feedwater must be heated from 80°C before it becomes steam at the given enthalpy."},{"prompt":"Divide heat recovered by heat per kg.","answer":"264,000 / 570.57 = 462.7 kg/h.","explain":"This gives the steam generation rate."}],"order":3462},
{"id":"p3-b09-036","paper":3,"topic":"DG Set Systems","kind":"problem","front":"A DG set at 750 kW with 440°C exhaust gas (8 kg gas/kWh, 0.25 kcal/kg°C) drops to 190°C after a heat recovery boiler. Steam enthalpy is 650 kcal/kg and feedwater is 70°C. How much steam is generated?","back":"About 647 kg/h.","explain":"This follows the same method as the chapter's worked example. The steam rate is the heat recovered divided by the enthalpy rise per kg of feedwater.","flash":false,"source":"BEE Book 3 Ch 09 p301","steps":[{"prompt":"Find the gas flow.","answer":"750 × 8 = 6,000 kg/h.","explain":"8 kg of gas is generated per kWh."},{"prompt":"Find the temperature drop.","answer":"440 − 190 = 250°C.","explain":"The exhaust gas is cooled from 440°C to 190°C in the boiler."},{"prompt":"Find the heat recovered.","answer":"6,000 × 0.25 × 250 = 3,75,000 kcal/h.","explain":"Heat = flow × specific heat × temperature drop."},{"prompt":"Find the steam generated.","answer":"3,75,000 / (650 − 70) = 646.6 ≈ 647 kg/h.","explain":"Heat per kg is the steam enthalpy minus the feedwater temperature."}],"order":3463},
{"id":"p3-b09-037","paper":3,"topic":"DG Set Systems","kind":"problem","front":"A 6 MW furnace oil DG set averages 5 MW and burns 1230 litres/h at Rs 28/litre. What is the fuel cost of generation in Rs/kWh?","back":"About Rs 6.89/kWh (furnace oil only).","explain":"The chapter gives no gas fuel price, so only the furnace oil cost is computed. The answer is the fuel cost per kWh delivered at the average load.","flash":false,"source":"BEE Book 3 Ch 09 p301","steps":[{"prompt":"Find the hourly fuel cost.","answer":"1230 × 28 = Rs 34,440 per hour.","explain":"Cost = litres per hour × price per litre."},{"prompt":"Find the energy generated per hour.","answer":"Average load 5 MW = 5,000 kWh/h.","explain":"At steady average load, kWh per hour equals kW."},{"prompt":"Find the cost per kWh.","answer":"34,440 / 5,000 = Rs 6.89/kWh.","explain":"Divide hourly fuel cost by hourly energy generated."}],"order":3464},
{"id":"p3-b09-038","paper":3,"topic":"DG Set Systems","kind":"problem","front":"How much energy does a 3.5 MW DG set generate in a year at 80% load factor for 7000 hours?","back":"About 1.96 × 10⁷ kWh (19,600 MWh).","explain":"Energy = rated kW × load factor × hours. The waste heat part of this question needs the exhaust temperature, which the chapter's question data does not give.","flash":false,"source":"BEE Book 3 Ch 09 p301","steps":[{"prompt":"Find the average load in kW.","answer":"3.5 MW × 0.80 = 2.8 MW = 2,800 kW.","explain":"The load factor is the average load as a fraction of the rated capacity."},{"prompt":"Find the annual energy generated.","answer":"2,800 kW × 7,000 h = 19,600,000 kWh (19,600 MWh).","explain":"Energy = average kW × operating hours."}],"order":3465},
{"id":"p3-b10-001","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What is the purpose of the Energy Conservation Building Code (ECBC)?","back":"It sets the minimum energy efficiency standards for the design and construction of commercial buildings, encouraging efficient design or major retrofit without compromising building function, comfort, health or occupant productivity.","explain":"ECBC is a code with minimum requirements, aimed at new commercial buildings and major retrofits. The chapter stresses that efficiency must not come at the cost of function, comfort or productivity.","flash":false,"source":"BEE Book 3 Ch 10 p305","order":3466},
{"id":"p3-b10-002","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Under the Energy Conservation (Amendment) Act 2010, what connected load or contract demand makes a commercial structure a ‘building’?","back":"A connected load of 100 kW or more, or a contract demand of 120 kVA or more, used or intended for commercial purposes.","explain":"The definition also covers existing structures that meet these ratings. Note that load is given in kW and contract demand in kVA, so the two thresholds are not interchangeable.","flash":false,"source":"BEE Book 3 Ch 10 p305","order":3467},
{"id":"p3-b10-003","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Name the five climatic zones into which India is divided for ECBC.","back":"Composite, Hot Dry, Warm Humid, Moderate and Cold.","explain":"The climate zone sets the climate-based prescriptive values for walls, roofs and windows, so the zone must be identified before choosing a compliance path. Figure 10.1 shows the zone map. ‘Cold-humid’ is not one of the five zones.","flash":true,"source":"BEE Book 3 Ch 10 p305","order":3468},
{"id":"p3-b10-004","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Which aspects of a building does the ECBC cover?","back":"Building envelope (except unconditioned storage spaces or warehouses); mechanical systems including HVAC; service hot water; interior and exterior lighting; and electrical power and motors.","explain":"These five areas are the subject of the code’s Chapters 4 to 8. The envelope rules do not apply to unconditioned storage spaces or warehouses.","flash":false,"source":"BEE Book 3 Ch 10 p306","order":3469},
{"id":"p3-b10-005","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What does the ECBC NOT apply to?","back":"Buildings that use neither electricity nor fossil fuel, and equipment or building-system portions that use energy primarily for manufacturing processes.","explain":"The exclusions depend on the energy source and on process use, not on building size. Process equipment in a factory is outside the code, but the building’s own HVAC and lighting are still covered.","flash":false,"source":"BEE Book 3 Ch 10 p306","order":3470},
{"id":"p3-b10-006","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Name the three ECBC compliance approaches for the building envelope.","back":"Prescriptive approach, envelope trade-off approach, and Whole Building Performance (WBP) approach.","explain":"The building must first meet all mandatory provisions. Prescriptive is quick but rigid, trade-off lets efficiency shift between roof, walls and windows, and WBP uses energy simulation and is the most flexible but needs the most effort.","flash":false,"source":"BEE Book 3 Ch 10 p314","order":3471},
{"id":"p3-b10-007","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"How does the Whole Building Performance method show ECBC compliance?","back":"The estimated annual energy use of the Proposed Design is compared with that of the Standard Design (the same building meeting all prescriptive requirements). Compliance requires the Proposed Design to use no more energy than the Standard Design.","explain":"The Standard Design sets the upper limit of allowed energy use. The method needs approved simulation software (Appendix B of the Code) and close coordination across the design team.","flash":false,"source":"BEE Book 3 Ch 10 p307","order":3472},
{"id":"p3-b10-008","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Name five areas of the building envelope that must be sealed, caulked, gasketed or weather-stripped.","back":"Joints around fenestration and door frames; openings between walls and foundations, roof or wall panels; openings where utility services penetrate roofs, walls or floors; site-built fenestration and doors; building assemblies used as ducts or plenums; and all other envelope openings.","explain":"Air leakage through the envelope adds an infiltration load that the HVAC system must then condition. The chapter lists the areas as a to f, and any other opening in the envelope must also be sealed.","flash":false,"source":"BEE Book 3 Ch 10 p308","order":3473},
{"id":"p3-b10-009","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"In a hot climate, how should buildings be oriented to limit solar gain?","back":"Minimise exposure to the east and west, since these faces get the highest solar heat gain. The long sides of buildings should face north and south.","explain":"Plot lines and roads should be laid out to limit east and west exposure. The chapter notes that good orientation can be achieved at no added cost when planned early.","flash":false,"source":"BEE Book 3 Ch 10 p309","order":3474},
{"id":"p3-b10-010","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What two properties define a cool roof, and what are the ECBC prescriptive minimum values?","back":"High solar reflectance and high thermal emittance. Minimum solar reflectance 0.7 and initial emittance 0.75.","explain":"A cool roof reflects sunlight and radiates absorbed heat back to the environment, so less heat passes into the building below. Values must be determined by the standards the code specifies.","flash":true,"source":"BEE Book 3 Ch 10 p314","order":3475},
{"id":"p3-b10-011","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What does visible light transmittance (VLT) measure, and why does it matter?","back":"The fraction of visible light passing through glazing. It counts only the visible part of the solar spectrum, unlike SHGC, which counts all solar radiation.","explain":"VLT is the key parameter for daylighting, because it shows how much usable light gets in. A window can have a low SHGC and a high VLT, which is the goal of spectral selectivity.","flash":false,"source":"BEE Book 3 Ch 10 p310","order":3476},
{"id":"p3-b10-012","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"How is window-to-wall ratio (WWR) defined?","back":"Vertical fenestration area divided by gross exterior wall area. Gross wall area is measured from the top of the floor to the bottom of the roof.","explain":"WWR is used to select the fenestration requirement and to calculate effective aperture. Only vertical fenestration counts, so skylights are not included.","flash":false,"source":"BEE Book 3 Ch 10 p311","order":3477},
{"id":"p3-b10-013","paper":3,"topic":"Buildings & ECBC","kind":"problem","front":"A building has a WWR of 0.4 and glazing with a VLT of 0.26. Does the glazing comply with ECBC by the effective aperture test (EA above 0.1)?","back":"Yes. EA = 0.26 × 0.4 = 0.104, which is above 0.1, so the glazing complies.","explain":"Effective aperture combines how much light the glazing passes with how much of the wall is glazed. Aperture size alone is not a good measure, because tinted or low-VLT glazing admits less light.","flash":false,"source":"BEE Book 3 Ch 10 p312","steps":[{"prompt":"Write the effective aperture formula.","answer":"EA = VLT × WWR","explain":"Light admitted depends on the glazing’s visible transmittance and on the glazed share of the wall."},{"prompt":"Calculate EA.","answer":"0.26 × 0.4 = 0.104","explain":"Multiply the VLT by the window-to-wall ratio."},{"prompt":"Compare EA with the 0.1 test value.","answer":"0.104 is above 0.1, so the glazing complies with ECBC.","explain":"The chapter’s worked example uses 0.1 as the pass mark."}],"order":3478},
{"id":"p3-b10-014","paper":3,"topic":"Buildings & ECBC","kind":"problem","front":"A building has a WWR of 0.6 and glazing with a VLT of 0.15. Does it comply by the EA test (EA above 0.1)? What minimum VLT would pass at this WWR?","back":"No. EA = 0.15 × 0.6 = 0.09, below 0.1. At WWR 0.6 the VLT must be at least about 0.17 (0.1 ÷ 0.6).","explain":"A higher WWR means more glazing, so the glass must transmit more light per unit of wall area to keep EA up. The 0.17 figure is derived from the chapter’s 0.1 test value rather than stated in the text.","flash":false,"source":"BEE Book 3 Ch 10 p312","steps":[{"prompt":"Write the effective aperture formula.","answer":"EA = VLT × WWR","explain":"EA is the effective daylight opening after the glazing’s transmittance is applied."},{"prompt":"Calculate EA for this glazing.","answer":"0.15 × 0.6 = 0.09","explain":"Multiply the VLT by the window-to-wall ratio."},{"prompt":"Compare EA with 0.1.","answer":"0.09 is below 0.1, so the glazing does not comply.","explain":"Failing this test means the glazing or the glazed area must change."},{"prompt":"Find the minimum VLT at WWR 0.6.","answer":"VLT ≥ 0.1 ÷ 0.6 ≈ 0.17","explain":"Rearranging EA = VLT × WWR gives the required VLT for the same test value."}],"order":3479},
{"id":"p3-b10-015","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What are the ECBC maximum U-factor and SHGC limits for vertical fenestration in the Composite zone?","back":"Maximum U-factor 3.30 W/m²·°C; maximum SHGC 0.25 where WWR is below 40%, and 0.20 where WWR is 40% to 60%.","explain":"As the glazed share of the wall grows, the SHGC limit gets tighter. The OCR of Table 10.3 was partly broken, so check these values against the printed table before relying on them.","flash":false,"source":"BEE Book 3 Ch 10 p314","order":3480},
{"id":"p3-b10-016","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What is the ECBC limit on skylight area under the prescriptive approach?","back":"Skylight area is limited to a maximum of 5% of the gross roof area. Skylights must also meet maximum U-factor and SHGC values.","explain":"The cap stops daylight gain from becoming excess heat and glare. This is the prescriptive skylight requirement in ECBC 4.3.4.","flash":true,"source":"BEE Book 3 Ch 10 p314","order":3481},
{"id":"p3-b10-017","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Which building components can be traded off against each other under the envelope trade-off approach, and what must be shown?","back":"Trade-offs are allowed only among the major envelope components: roof, walls and fenestration. The proposed design’s Envelope Performance Factor (EPF) must be equal to or better than the baseline design’s EPF.","explain":"EPF is calculated using Appendix D of the ECBC. Trade-offs cannot cross into HVAC or lighting; those systems have their own requirements.","flash":false,"source":"BEE Book 3 Ch 10 p315","order":3482},
{"id":"p3-b10-018","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What HVAC controls does ECBC require for equipment above 28 kW cooling or 7 kW heating?","back":"A time clock that keeps its programme for at least 10 hours and controls varying schedules. Each zone needs its own temperature controller, heating-and-cooling equipment needs a 3 °C (5 °F) dead band, and thermostats must prevent simultaneous heating and cooling.","explain":"The time clock lets equipment run only when it is needed. The dead band keeps the heating and cooling set points apart so one does not fight the other.","flash":false,"source":"BEE Book 3 Ch 10 p315","order":3483},
{"id":"p3-b10-019","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"True or false: spiral lock joints in round and flat oval ducts must be sealed.","back":"False. Spiral lock joints need not be sealed. Longitudinal seams and transverse joints do need sealing.","explain":"Leaks let conditioned air escape to unconditioned spaces or outdoors. The chapter calls duct sealing one of the most important conservation checks, and ducts in unconditioned spaces also need insulation.","flash":false,"source":"BEE Book 3 Ch 10 p316","order":3484},
{"id":"p3-b10-020","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Which hydronic pumps must have variable speed drives under ECBC, and what flow range must they allow?","back":"Pump motors of 3.7 kW (5 HP) and above in all hydronic systems must have variable speed drives. Pump flow must be controllable down to 50% of design, or the manufacturer’s minimum for the chiller or boiler.","explain":"Throttling keeps the motor at full speed and wastes energy. A variable speed drive lowers the motor speed and power while still delivering the required flow.","flash":false,"source":"BEE Book 3 Ch 10 p317","order":3485},
{"id":"p3-b10-021","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"When does ECBC require an economizer on a cooling system?","back":"When the fan capacity is above 1,200 L/s (2,500 cfm) and the cooling capacity is above 22 kW.","explain":"An economizer cools with outside air when temperature and humidity are mild, instead of running refrigeration on recirculated air. A properly operating economizer can cut a building’s total energy use by as much as 10%.","flash":false,"source":"BEE Book 3 Ch 10 p318","order":3486},
{"id":"p3-b10-022","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"For residential facilities, hotels and hospitals with a centralised system, what share of design capacity must come from solar water heating?","back":"At least 20% of the design capacity.","explain":"Supplementary heating must be cascaded: heat recovery from hot discharge (such as AC condensers) first, then gas-fired heaters where gas is available, and an electric heater only as a last resort.","flash":true,"source":"BEE Book 3 Ch 10 p318","order":3487},
{"id":"p3-b10-023","paper":3,"topic":"Buildings & ECBC","kind":"problem","front":"A hotel has four floors of 1000 m² each. If the LPD is 10.8 W/m², what is the interior lighting power allowance by the building area method?","back":"43,200 W (43.2 kW).","explain":"Under the building area method, the allowance is the sum of gross lighted floor area times the allowed LPD for each building area type. The four floors here are treated as one type, so the total area is multiplied by the LPD.","flash":false,"source":"BEE Book 3 Ch 10 p319","steps":[{"prompt":"Find the total gross lighted floor area.","answer":"4 × 1000 m² = 4000 m²","explain":"The building area method uses the gross lighted floor area of each building area type."},{"prompt":"Multiply the total area by the LPD.","answer":"4000 m² × 10.8 W/m² = 43,200 W","explain":"Allowance in watts equals area times the allowed watts per square metre."},{"prompt":"Express the result in kilowatts.","answer":"43,200 W = 43.2 kW, the interior lighting power allowance.","explain":"The installed interior lighting load is compared with this allowance to check compliance."}],"order":3488},
{"id":"p3-b10-024","paper":3,"topic":"Buildings & ECBC","kind":"problem","front":"An enclosed office has an area of 400 m². If the LPD is 11.8 W/m², what is its interior lighting power allowance by the space function method?","back":"4720 W (4.72 kW).","explain":"Under the space function method, the building allowance is the sum of the allowances for all spaces, and each space’s allowance is its gross lighted floor area times the LPD for that space type.","flash":false,"source":"BEE Book 3 Ch 10 p320","steps":[{"prompt":"Identify the method and its rule.","answer":"Space function method: each space gets area × LPD for its type, and the building total is the sum over all spaces.","explain":"This method suits buildings with mixed space types, such as offices, corridors and storage."},{"prompt":"Calculate the office allowance.","answer":"400 m² × 11.8 W/m² = 4720 W","explain":"Use the gross lighted floor area of the enclosed office."},{"prompt":"Build the building total.","answer":"Add the allowance of every other space to 4720 W to get the building allowance.","explain":"The office figure is one term in the sum over all spaces."}],"order":3489},
{"id":"p3-b10-025","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What is the ECBC rule for exit signs?","back":"An internally-illuminated exit sign must not exceed 5 W per face.","explain":"An exit sign is lit continuously, so its wattage per face adds up over the building’s life. The chapter also suggests changing exit signs from incandescent to LED.","flash":true,"source":"BEE Book 3 Ch 10 p320","order":3490},
{"id":"p3-b10-026","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What lamp efficacy does ECBC require for exterior grounds luminaires above 100 W, and what exception applies?","back":"A minimum efficacy of 60 lm/W, unless the luminaire is controlled by a motion sensor.","explain":"Exterior lighting must also be controlled by a photo sensor or an astronomical time switch that turns it off when daylight is available or the light is not needed.","flash":false,"source":"BEE Book 3 Ch 10 p320","order":3491}
]$cards$::jsonb);
